/** Collapse a preview to a single-line, length-capped lesson text. */
function toLessonText(preview: string, cap = 240): string {
  const oneLine = preview.replace(/\s+/g, " ").trim();
  return oneLine.length > cap ? oneLine.slice(0, cap - 1) + "…" : oneLine;
}

/**
 * Trust band for a candidate. A session whose secret-scan was NOT clean is
 * `untrusted` (its content is suspect); a subagent/fork derivative is `derived`;
 * a clean top-level session is `trusted`.
 */
function trustFor(rec: CapturedSession): LessonTrust {
  if (!rec.secretScan.clean) return "untrusted";
  if (rec.subagentOf || rec.forkOf) return "derived";
  return "trusted";
}

/* -------------------------------------------------------------------------- */
/*  Extraction                                                                 */
/* -------------------------------------------------------------------------- */

export interface ExtractionOptions {
  /** Min recurrences for a "recurring pattern" candidate. Default 3. */
  recurringThreshold?: number;
}

/**
 * Produce DRAFT lesson candidates from a set of captured records. Pure +
 * deterministic. Does NOT touch Convex — the CLI/caller pushes the results via
 * `upsertLesson`.
 */
export function extractLessonCandidates(
  records: CapturedSession[],
  opts: ExtractionOptions = {},
): LessonCandidate[] {
  const recurringThreshold = opts.recurringThreshold ?? 3;
  const candidates: LessonCandidate[] = [];

  // 1. Per-record marker / error→correction candidates (need a preview).
  for (const rec of records) {
    const preview = rec.preview?.trim();
    if (!preview) continue;

    const hasMarker = MARKER_RE.test(preview);
    const hasError = ERROR_RE.test(preview);
    if (!hasMarker && !hasError) continue;

    const reason = hasMarker
      ? "explicit-lesson-marker"
      : "error-correction-signal";
    const text = `${hasMarker ? "Leçon" : "Correction"}: ${toLessonText(preview)}`;
    candidates.push({
      text,
      projectSlug: rec.projectSlug,
      dedupKey: dedupFingerprint([rec.projectSlug ?? "", reason, preview]),
      sourceSessionIds: [rec.sessionId],
      trust: trustFor(rec),
      reason,
    });
  }

  // 2. Recurring-theme candidates: group by (projectSlug, agentType) and emit a
  //    pattern when the same project repeatedly spawns the same agent type — a
  //    proxy for "this project keeps needing this kind of work".
  const themes = new Map<
    string,
    { projectSlug?: string; agentType: string; sessions: string[] }
  >();
  for (const rec of records) {
    if (!rec.agentType) continue;
    const key = `${rec.projectSlug ?? ""}::${rec.agentType}`;
    const entry =
      themes.get(key) ??
      { projectSlug: rec.projectSlug, agentType: rec.agentType, sessions: [] };
    entry.sessions.push(rec.sessionId);
    themes.set(key, entry);
  }
  for (const { projectSlug, agentType, sessions } of themes.values()) {
    if (sessions.length < recurringThreshold) continue;
    const text = `Motif récurrent: ce projet sollicite régulièrement des agents « ${agentType} » (${sessions.length} sessions).`;
    candidates.push({
      text,
      projectSlug,
      dedupKey: dedupFingerprint([projectSlug ?? "", "recurring", agentType]),
      sourceSessionIds: sessions.slice(0, 50),
      trust: "derived",
      reason: "recurring-agent-theme",
    });
  }

  // Deterministic order (by dedupKey) so repeated runs are stable.
  return candidates.sort((a, b) => a.dedupKey.localeCompare(b.dedupKey));
}

